        for x in variables:
            clauses.append([x])
        for i in range(1, n):
            clauses.append([f'~{variables[i-1]}', f'{variables[i]}'])
        return clauses

    def configuration_space_metric(clauses):
        points = []
        distances = []
        for clause in clauses:
            if len(clause) == 1:
                point = [0] * n
                point[variables.index(clause[0])] = 1
                points.append(point)
            else:
                point1 = [0] * n
                point2 = [0] * n
                for var in clause:
                    if var.startswith('~'):
                        point1[variables.index(var[1:])] = -1
                    else:
                        point2[variables.index(var)] = 1
                points.append(point1)
                points.append(point2)
                distances.append(2)
        return points, distances

    def min_rank(points):
        A = []
        for point in points:
            row = [point[i]**2 for i in range(n)]
            A.append(row)
        rank = gaussian_elimination(A)
        if rank is None:
            return float('inf')
        return len(rank)

    n_values = [5, 10, 15, 20, 30, 40]
